import{_ as a,o as n,c as i,a5 as t}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan - FR 3.5.6","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-6-approve-media-campaign/plan.md","filePath":"feature/media-package-campaign/3-5-6-approve-media-campaign/plan.md"}'),r={name:"feature/media-package-campaign/3-5-6-approve-media-campaign/plan.md"};function o(s,e,d,l,p,c){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="plan-fr-3-5-6" tabindex="-1">Plan - FR 3.5.6 <a class="header-anchor" href="#plan-fr-3-5-6" aria-label="Permalink to &quot;Plan - FR 3.5.6&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Implement E50-07 campaign approval and idempotent task deployment.</p><p>2026-10-08: M2 approval can be delivered before M3 deployment. See <a href="./../campaign-delivery-plan.html">delivery plan</a>. Mongo V2 is confirmed; deployment still requires editor integration and explicit launch conditions.</p><p>Stage 3 adds <code>campaign_versions</code> and append-only <code>campaign_review_events</code>, plus actor/version columns on <code>media_campaigns</code>. The Workspace API exposes feedback, versions and approval. Agreement row locking serializes concurrent edits and approvals; a stale version returns 409. Inbox notifications use the existing <code>user_notifications</code> table and the Campaign Workspace URL.</p><p>Stage 4 uses deterministic UUIDs derived from Campaign ID and work item ID, Mongo insert-only upserts, a partial unique index on <code>(campaignId, campaignWorkItemId)</code>, and PostgreSQL deployment state. A retry reads the same approved snapshot and inserts only missing Tasks. No Mongo database init or account seed is part of the change. Editor REST and WebSocket access validate the Mongo Task and current Workspace membership; PostgreSQL Yjs foreign keys become soft references while the old Task table remains for read-only audit.</p><p>Before the PostgreSQL FK migration, preflight must show no unmigrated Task IDs. The local preflight is 0 Task, 0 operation, 0 snapshot. Other environments need their own backfill and reconciliation before application rollout. Mongo validator and index migration is applied separately on the existing Atlas database.</p><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><ol><li>Reuse the confirmed two-party campaign approval rule.</li><li>Increment campaign content version/reset both approvals on a pre-final-approval edit.</li><li>Implement the Mongo backlog adapter and integrate the existing editor. Use task insert-only upserts keyed by campaign ID and stable work-item ID, with a partial unique index for campaign-generated tasks.</li><li>Record deployment progress/retry state durably in PostgreSQL; resume after failure or restart, and ensure retries never overwrite a Task already being worked on.</li><li>Mark campaign <code>IN_PROGRESS</code> only after all work-item tasks are durable.</li><li>Test double deploy and mid-deployment retry without duplicates.</li><li>Add approval/launch UI with version indicators, opposite-side inbox notifications, paired vi/en text, light/dark states and recoverable failure feedback.</li><li>Implement Client feedback and Manager edits; add explicit Manager completion from IN_PROGRESS, requiring a reason if Tasks are unfinished. Preserve Task states/workflow; see <a href="./../phase-1-design/plan.html">phase-1 contract</a> for retries, metadata and Mongo failure handling.</li></ol><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p>Requires E50-06 work items and E51-01 generic tasks.</p>',11)])])}const h=a(r,[["render",o]]);export{g as __pageData,h as default};
